import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.DMvgf4hZ.js";const l="/toonflow/assets/plugin-market.CdFD2jWq.png",m=JSON.parse('{"title":"插件市场","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plugin-market.md","filePath":"guide/plugin-market.md","lastUpdated":1794884041000}'),d={name:"guide/plugin-market.md"};function n(i,t,s,h,f,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="插件市场" tabindex="-1">插件市场 <a class="header-anchor" href="#插件市场" aria-label="Permalink to &quot;插件市场&quot;">​</a></h1><ol><li>点击“设置 → 插件市场”，在“发现插件”搜索需要的功能，点击卡片阅读说明，再点击“安装”。页面要求验证时，填写 TF-Router API Key 并点击“保存并继续”。</li><li>安装后切到“已安装”查看；卡片有“配置”时，先填写需要的内容并保存。已有本地插件文件，可点击这里的“安装插件”导入；市场显示“更新”时可更新该插件。</li><li>节点装好后，在画布右键菜单或 Tab 菜单中使用；技能在助手输入区的书本按钮中选择；工具由助手根据你的要求调用。</li><li>例如，安装画布节点可增加制作方式，安装技能可补充创作流程，安装工具可增加搜索或文件操作能力。Agent 类别显示“测试阶段，暂未开放”时，先使用已有类别。</li></ol><p><img src="'+l+'" alt="插件市场的发现插件与已安装列表"></p><h2 id="扩展类型" tabindex="-1">扩展类型 <a class="header-anchor" href="#扩展类型" aria-label="Permalink to &quot;扩展类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>扩展类型</th><th>用途</th><th>开发入口</th></tr></thead><tbody><tr><td>节点</td><td>为画布增加交互组件、输入输出端口与节点操作。</td><td><a href="https://github.com/dolfly/toonflow/blob/master/packages/nodeScaffold/readme.md" target="_blank" rel="noreferrer">节点脚手架</a></td></tr><tr><td>工具</td><td>为 Agent 增加工作区操作、搜索、媒体生成等能力，可附带交互 UI。</td><td><a href="https://github.com/dolfly/toonflow/blob/master/packages/toolScaffold/readme.md" target="_blank" rel="noreferrer">工具脚手架</a></td></tr><tr><td>技能</td><td>用 <code>SKILL.md</code> 和附属资料描述创作流程、方法与操作约定。</td><td><a href="https://github.com/dolfly/toonflow/tree/master/packages/skills" target="_blank" rel="noreferrer">内置技能</a></td></tr><tr><td>提供方</td><td>适配不同平台的模型列表、请求参数和媒体返回结果。</td><td><a href="https://github.com/dolfly/toonflow/tree/master/packages/providers/src" target="_blank" rel="noreferrer">提供方实现</a></td></tr></tbody></table><p>也可以在桌面客户端里通过 <code>toonflow://install</code> 链接唤起安装，或用第三方 Coding 工具通过 MCP 操作 Toonflow。这两条路径的细节见<a href="/toonflow/development/plugins.html">插件、技能与提供方</a>。</p><h2 id="插件从哪来" tabindex="-1">插件从哪来 <a class="header-anchor" href="#插件从哪来" aria-label="Permalink to &quot;插件从哪来&quot;">​</a></h2><ul><li>网页版市场：<a href="https://api.toonflow.net/console/plugIn" target="_blank" rel="noreferrer">https://api.toonflow.net/console/plugIn</a></li><li>自己写：本站<a href="/toonflow/plugins/">插件开发</a> 分区，从「01 · 开发总览」到「07 · 发布插件」覆盖工具、节点、技能全流程；安装契约见<a href="/toonflow/development/plugins.html">插件、技能与提供方</a></li></ul>',8)])])}const g=e(d,[["render",n]]);export{m as __pageData,g as default};
